var t=`0347-spatzle`;var n=`world-0347`;var s=`DE`;var a=`western-europe`;var r=4;var l=21;var o={en:`Spätzle`,ua:`Шпецле`};var g={en:`A traditional Germany dish made with all-purpose flour, chicken egg, parsley. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Німеччина. Основні інгредієнти: пшеничне борошно універсальне, куряче яйце, петрушка. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var u=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`all-purpose-flour`,350,`g`],[`chicken-egg`,4,`pcs`],[`water`,150,`ml`],[`table-salt`,5,`g`]]},{en:`Press or scrape the soft egg dough into gently boiling water in small batches; cook until the spätzle rise to the surface, about 3 minutes per batch, then drain.`,ua:`Протисніть або зіскребіть м’яке яєчне тісто в ледь киплячу воду невеликими порціями; варіть, доки шпецле спливуть, приблизно 3 хвилини на партію, потім відцідіть.`,t:[`boiling`],m:8,i:[[`water`,1600,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`unsalted-butter`,70,`g`],[`parsley`,17,`g`]]}];var d={slug:t,id:n,country:`DE`,region:a,servings:4,minutes:21,title:o,text:g,steps:u};export{s as country,d as default,n as id,l as minutes,a as region,r as servings,t as slug,u as steps,g as text,o as title};